import os, re, csv, datetime

REF = datetime.date(2025, 8, 12)
levels = ["ERROR", "WARNING", "INFO"]
periods = ["today", "last_7_days", "last_30_days", "month_to_date", "total"]

# define ranges inclusive (start, end)
ranges = {
    "today": (REF, REF),
    "last_7_days": (REF - datetime.timedelta(days=6), REF),
    "last_30_days": (REF - datetime.timedelta(days=29), REF),
    "month_to_date": (REF.replace(day=1), REF),
}

counts = {p: {l: 0 for l in levels} for p in periods}
fname_re = re.compile(r"^(\d{4}-\d{2}-\d{2})_.*\.log$")
sev_re = re.compile(r"\[(ERROR|WARNING|INFO)\]")

for fn in sorted(os.listdir("/app/logs")):
    m = fname_re.match(fn)
    if not m:
        continue
    d = datetime.datetime.strptime(m.group(1), "%Y-%m-%d").date()
    local = {l: 0 for l in levels}
    with open(os.path.join("/app/logs", fn), errors="replace") as f:
        for line in f:
            sm = sev_re.search(line)
            if sm:
                local[sm.group(1)] += 1
    for p, (s, e) in ranges.items():
        if s <= d <= e:
            for l in levels:
                counts[p][l] += local[l]
    for l in levels:
        counts["total"][l] += local[l]

with open("/app/summary.csv", "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["period", "severity", "count"])
    for p in periods:
        for l in levels:
            w.writerow([p, l, counts[p][l]])

print(open("/app/summary.csv").read())
